import networkx as nx
G = nx.Graph()
for i in range(18):
    G.add_node(i)
for i in range(18):
    for j in range(i+1, 18):
        if len(list(G.neighbors(i))) < 6 and len(list(G.neighbors(j))) < 6:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 6 or len(list(G.neighbors(j))) == 6:
                break
if min(list(G.degree())) < 4 or max(list(G.degree())) > 6:
    print("UNSATISFIABLE")
else:
    print(list(G.edges()))
